using UnityEngine;
using UnityEditor;

namespace Slax.QuestSystem
{
    [CustomEditor(typeof(QuestManager))]
    public class QuestManagerEditor : Editor
    {
        bool showSaveBox = true;
        bool showManualOperations = false;

        public override void OnInspectorGUI()
        {
            QuestManager obj = (QuestManager)target;
            SerializedProperty saveType = serializedObject.FindProperty("_saveType");
            SerializedProperty returnType = serializedObject.FindProperty("_returnType");
            SerializedProperty questLineAssetPath = serializedObject.FindProperty("_questLineAssetPath");
            SerializedProperty questAssetPath = serializedObject.FindProperty("_questAssetPath");
            SerializedProperty questStepAssetPath = serializedObject.FindProperty("_questStepAssetPath");

            GUILayout.Box("The Quest Manager handles all quest related operations. \n Quest completion, quest events, saving and loading etc. It is easy to customize as well.", EditorStyles.helpBox);

            GUILayout.Space(30);

            EditorGUI.indentLevel = 1;
            GUILayout.Label("Quests Configuration", EditorStyles.boldLabel);
            DrawDefaultProp("_questLines");
            GUILayout.Space(10);

            EditorGUI.indentLevel = 0;
            GUILayout.Space(30);

            GUILayout.Label("Save Configuration", EditorStyles.boldLabel);
            EditorGUI.indentLevel = 1;
            GUI.backgroundColor = Color.cyan;
            showSaveBox = EditorGUILayout.Foldout(showSaveBox, "Save Configuration Details");
            if (showSaveBox)
            {
                GUILayout.Box("This Manager allows you to use either its internal saving system which will save Quests data to a separate save file or have it return save data in a format of choice to plug in your own save data. \n Set Save Type to Custom if you need to plug it into your own save system, or leave it as Internal to let the Quest Manager handle it for you.", EditorStyles.helpBox);
            }
            GUILayout.Space(10);
            DrawDefaultProp("_saveType");
            string selectedSaveType = saveType.enumNames[saveType.enumValueIndex];

            if (selectedSaveType == "Custom")
            {
                DrawDefaultProp("_returnType");
            }
            else
            {
                DrawDefaultProp("_saveFileName");
            }
            EditorGUI.indentLevel = 0;

            GUILayout.Space(30);

            // Manual actions
            GUI.backgroundColor = Color.yellow;
            showManualOperations = EditorGUILayout.Foldout(showManualOperations, "Manual Operations (testing)");
            if (showManualOperations)
            {
                GUILayout.Label("Manual Operations", EditorStyles.boldLabel);
                if (GUILayout.Button(new GUIContent("Manual Reset", "Resets the Quest Manager, marking all quests are incomplete in the current instance of the Quest Manager."), GUILayout.Height(30)))
                {
                    obj.ManualReset();
                }
                if (GUILayout.Button(new GUIContent("Manual Save", "Saves the current quest progress to the save file at the specified path."), GUILayout.Height(30)))
                {
                    obj.ManualSave();
                }
            }

            serializedObject.ApplyModifiedProperties();
        }

        void DrawDefaultProp(string propName)
        {
            EditorGUILayout.PropertyField(serializedObject.FindProperty(propName));
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEditor;
using static UnityEditor.EditorGUILayout;

namespace Slax.QuestSystem
{
    public class QuestManagerEditorWindow : EditorWindow
    {
        private enum BackgroundType { AssetCreator, AssetFinder, QuestInfo, QuestLineDetails }

        private Vector2 _scroll;
        private int _selected;
        private Texture2D _searchIcon;
        private Texture2D _refreshIcon;

        List<string> _SOTypes = new List<string>();

        string[] _questLineGUIDs;
        string[] _questGUIDs;
        string[] _questStepGUIDs;

        QuestLineSO[] _questLineObjects;
        QuestSO[] _questObjects;
        QuestStepSO[] _questStepObjects;

        string[] _displayObjectsGUIDs;
        List<string> _displayObjectsPaths;
        List<ScriptableObject> _displayObjects;

        string _questLineAssetPath = "Assets/QuestSystem/QuestLines";
        string _questAssetPath = "Assets/QuestSystem/Quests";
        string _questStepAssetPath = "Assets/QuestSystem/QuestSteps";

        int _lastSelectedTab = 0;
        ScriptableObject _lastCreatedAsset;

        private Dictionary<BackgroundType, Texture2D> _backgrounds;

        int _activeQuestLineInfo;

        private void OnEnable()
        {
            FindAllSOs();
            FindDisplaySOs();
            InitializeBackgrounds();
            LoadIcons();
        }

        void OnFocus()
        {
            FindAllSOs();
            FindDisplaySOs();
        }

        [MenuItem("Window/Slax/Quest Manager")]
        private static void ShowWindow()
        {
            GetWindow<QuestManagerEditorWindow>(false, "Quest Manager", true);
        }

        void OnGUI()
        {
            _scroll = BeginScrollView(_scroll, false, false);

            GUILayout.Space(EditorGUIUtility.singleLineHeight * 0.5f);
            BeginHorizontal();

            BeginVertical(GUILayout.ExpandWidth(true));
            GUILayout.Box("The Quest Manager helps create and manage all asset scriptable objects related to Quests in the project.");
            EndVertical();

            BeginVertical(GUILayout.Width(50));
            GUIContent refreshContent = new GUIContent(_refreshIcon);
            if (GUILayout.Button(refreshContent, GetSquareButtonStyle(30))) FindAllSOs();
            EndVertical();

            EndHorizontal();
            Space(15);

            BeginHorizontal();
            BeginVertical("box", GUILayout.Width(130), GUILayout.ExpandHeight(true));

            string[] tabs = { "Asset Creator", "Asset Finder", "Quest Info" };

            for (int i = 0; i < tabs.Length; i++)
            {
                bool tabSelected = GUILayout.Button(tabs[i]);
                if (tabSelected) _lastSelectedTab = i;
            }

            EndVertical();
            BeginVertical("box", GUILayout.ExpandHeight(true));
            if (_lastSelectedTab == 0)
            {
                LabelField("Quest asset creator", EditorStyles.boldLabel);
                HelpBox("When creating Quests it is recommended to follow the following pattern in order to keep things easy to maintain : QuestLineX_QuestX_StepX (shorter : QLX_QX_SX) where X is a number.", MessageType.Info);
                DrawAssetCreator("QuestLine");
                DrawAssetCreator("Quest");
                DrawAssetCreator("QuestStep");
            }
            else if (_lastSelectedTab == 1)
            {
                LabelField("Quest asset finder", EditorStyles.boldLabel);
                Space(15);

                GUILayout.BeginHorizontal();

                DrawSOsPicker();
                if (GUILayout.Button(refreshContent, GetSquareButtonStyle(30)))
                {
                    FindAllSOs();
                    FindDisplaySOs();
                }
                GUILayout.EndHorizontal();
                Space(15);
                LabelField("__________________________________________________");
                Space(15);

                DrawSOsList();
            }
            else
            {
                BeginHorizontal();
                DrawQuestConfigs();
                if (_activeQuestLineInfo <= _questLineObjects.Length)
                {
                    BeginVertical();
                    DrawSelectedQuestLineInfo();
                    EndVertical();
                }
                EndHorizontal();
            }

            EndVertical();
            EndHorizontal();
            Space(15);
            EndScrollView();
        }

        void DrawAssetCreator(string assetType)
        {
            Space(15);

            switch (assetType)
            {
                case "QuestLine":
                    // update questline in a field here
                    _questLineAssetPath = TextField("Quest Line Asset Path", _questLineAssetPath);
                    break;
                case "Quest":
                    _questAssetPath = TextField("Quest Asset Path", _questAssetPath);
                    break;
                case "QuestStep":
                    _questStepAssetPath = TextField("Quest Step Asset Path", _questStepAssetPath);
                    break;
                default:
                    break;
            }

            ScriptableObject createdAsset = null;

            switch (assetType)
            {
                case "QuestLine":
                    if (GUILayout.Button(new GUIContent("Create Quest Line", "Creates a new Quest Line asset Scriptable Object"), GUILayout.Height(20)))
                    {
                        createdAsset = QuestAssetCreator.CreateQuestLine(_questLineAssetPath);
                    }
                    break;
                case "Quest":
                    if (GUILayout.Button(new GUIContent("Create Quest", "Creates a new Quest asset Scriptable Object"), GUILayout.Height(20)))
                    {
                        createdAsset = QuestAssetCreator.CreateQuest(_questAssetPath);
                    }
                    break;
                case "QuestStep":
                    if (GUILayout.Button(new GUIContent("Create Quest Step", "Creates a new Quest Step asset Scriptable Object"), GUILayout.Height(20)))
                    {
                        createdAsset = QuestAssetCreator.CreateQuestStep(_questStepAssetPath);
                    }
                    break;
            }

            if (createdAsset)
            {
                EditorUtility.FocusProjectWindow();
                EditorGUIUtility.PingObject(createdAsset);
                FindAllSOs();
            }
        }

        void DrawSOsPicker()
        {
            EditorGUI.BeginChangeCheck();
            _selected = Popup(GUIContent.none, _selected, _SOTypes.ToArray());
            if (EditorGUI.EndChangeCheck())
            {
                FindDisplaySOs();
            }
        }

        void DrawQuestConfigs()
        {
            BeginVertical(GetBoxStyle(BackgroundType.QuestInfo), GUILayout.ExpandHeight(true), GUILayout.Width(250));
            if (_questLineGUIDs.Length == 0)
            {
                LabelField("No Quest Lines created");
                return;
            }

            for (int i = 0; i < _questLineGUIDs.Length; i++)
            {
                string assetPath = AssetDatabase.GUIDToAssetPath(_questLineGUIDs[i]);
                QuestLineSO questLine = (QuestLineSO)AssetDatabase.LoadAssetAtPath(assetPath, typeof(QuestLineSO));
                DrawQuestLineInfo(questLine, i);
            }
            EndVertical();
        }

        void DrawQuestLineInfo(QuestLineSO questLine, int index)
        {
            if (!questLine) return;
            BeginVertical(new GUIStyle(GetBoxStyle(BackgroundType.QuestLineDetails)));
            BeginHorizontal(GUILayout.ExpandWidth(true));
            int previewSize = 60;
            GUILayout.Label(questLine.Sprite.texture ? questLine.Sprite.texture : new Texture2D(previewSize, previewSize), GUILayout.Width(previewSize), GUILayout.Height(previewSize));

            BeginVertical();
            LabelField($"{questLine.DisplayName}", EditorStyles.boldLabel);
            GUILayout.Label($"Asset: {questLine.name}");
            if (GUILayout.Button(_searchIcon, GetSquareButtonStyle(22)))
            {
                EditorUtility.FocusProjectWindow();
                EditorGUIUtility.PingObject(questLine);
            }
            EndVertical();
            EndHorizontal();

            BeginHorizontal();
            BeginVertical();
            LabelField($"Quests: {questLine.Quests.Count}");
            LabelField($"Total Steps: {questLine.GetTotalSteps()}");
            EndVertical();

            BeginVertical();
            if (GUILayout.Button("Info"))
            {
                _activeQuestLineInfo = index;
            }
            EndVertical();
            EndHorizontal();
            EndVertical();
        }

        void DrawSelectedQuestLineInfo()
        {
            QuestLineSO questLine = _questLineObjects[_activeQuestLineInfo];
            if (!questLine) return;
            if (questLine.Quests.Count > 0)
            {
                questLine.Quests.ForEach((quest) =>
                {
                    BeginVertical("box");
                    LabelField($"{quest.DisplayName}", EditorStyles.boldLabel);

                    quest.Steps.ForEach((step) =>
                    {
                        GUI.color = step.Completed ? Color.green : Color.white;
                        LabelField($"- {step.DisplayName}", EditorStyles.boldLabel);
                    });
                    EndVertical();
                    GUI.color = Color.white;
                });
            }
        }

        void DrawSOsList()
        {
            _scroll = GUILayout.BeginScrollView(_scroll);

            for (int i = 0; i < _displayObjectsGUIDs.Length; i++)
            {
                BeginHorizontal(GUILayout.Width(250));
                GUILayout.Label(i + 1 + ". " + _displayObjects[i].name);

                if (GUILayout.Button(_searchIcon, GetSquareButtonStyle(27)))
                {
                    EditorUtility.FocusProjectWindow();
                    EditorGUIUtility.PingObject(_displayObjects[i]);
                }
                EndHorizontal();

                GUILayout.Space(EditorGUIUtility.singleLineHeight);
            }

            GUILayout.EndScrollView();
        }

        string[] FindQuestLinesGUIDs() => AssetDatabase.FindAssets("t:Slax.QuestSystem.QuestLineSO");
        string[] FindQuestGUIDs() => AssetDatabase.FindAssets("t:Slax.QuestSystem.QuestSO");
        string[] FindQuestStepGUIDs() => AssetDatabase.FindAssets("t:Slax.QuestSystem.QuestStepSO");

        void FindAllSOs()
        {
            _questLineGUIDs = FindQuestLinesGUIDs();
            _questGUIDs = FindQuestGUIDs();
            _questStepGUIDs = FindQuestStepGUIDs();

            _questLineObjects = new QuestLineSO[_questLineGUIDs.Length];
            _questObjects = new QuestSO[_questGUIDs.Length];
            _questStepObjects = new QuestStepSO[_questStepGUIDs.Length];

            for (int i = 0; i < _questLineGUIDs.Length; i++)
            {
                _questLineObjects[i] = (QuestLineSO)AssetDatabase.LoadAssetAtPath(AssetDatabase.GUIDToAssetPath(_questLineGUIDs[i]), typeof(QuestLineSO));
                _SOTypes.Add(_questLineObjects[i].GetType().ToString());
            }

            for (int i = 0; i < _questGUIDs.Length; i++)
            {
                _questObjects[i] = (QuestSO)AssetDatabase.LoadAssetAtPath(AssetDatabase.GUIDToAssetPath(_questGUIDs[i]), typeof(QuestSO));
                _SOTypes.Add(_questObjects[i].GetType().ToString());
            }

            for (int i = 0; i < _questStepGUIDs.Length; i++)
            {
                _questStepObjects[i] = (QuestStepSO)AssetDatabase.LoadAssetAtPath(AssetDatabase.GUIDToAssetPath(_questStepGUIDs[i]), typeof(QuestStepSO));
                _SOTypes.Add(_questStepObjects[i].GetType().ToString());
            }
        }

        void FindDisplaySOs()
        {
            if (_displayObjects != null)
            {
                _displayObjects.Clear();
            }
            if (_displayObjectsPaths != null)
            {
                _displayObjectsPaths.Clear();
            }

            if (_SOTypes.Count == 0) return;

            string type = _SOTypes[_selected];
            string queryString = "t:" + type;

            _displayObjectsGUIDs = AssetDatabase.FindAssets(queryString);

            _displayObjectsPaths = new List<string>(_displayObjectsGUIDs.Length);
            _displayObjects = new List<ScriptableObject>(_displayObjectsGUIDs.Length);

            for (int i = 0; i < _displayObjectsGUIDs.Length; i++)
            {
                _displayObjectsPaths.Add(AssetDatabase.GUIDToAssetPath(_displayObjectsGUIDs[i]));
                _displayObjects.Add(AssetDatabase.LoadAssetAtPath(_displayObjectsPaths[i], typeof(ScriptableObject)) as ScriptableObject);
            }
        }

        GUIStyle GetBoxStyle(BackgroundType backgroundType)
        {
            GUIStyle style = new GUIStyle() { padding = new RectOffset(10, 10, 10, 10) };
            style.normal.background = _backgrounds[backgroundType];
            return style;
        }

        void InitializeBackgrounds()
        {
            _backgrounds = new Dictionary<BackgroundType, Texture2D>();

            Texture2D assetCreator = new Texture2D(1, 1);
            assetCreator.SetPixel(1, 1, new Color(0.13f, 0.2f, 0.23f));
            assetCreator.Apply();
            _backgrounds.Add(BackgroundType.AssetCreator, assetCreator);

            Texture2D questInfo = new Texture2D(1, 1);
            questInfo.SetPixel(1, 1, new Color(0.13f, 0.2f, 0.23f));
            questInfo.Apply();
            _backgrounds.Add(BackgroundType.QuestInfo, questInfo);

            Texture2D questLineDetails = new Texture2D(1, 1);
            // questLineDetails.SetPixel(1, 1, new Color(0.37f, 0.31f, 0.25f));
            questLineDetails.SetPixel(1, 1, Color.clear);
            questLineDetails.Apply();
            _backgrounds.Add(BackgroundType.QuestLineDetails, questLineDetails);
        }

        void LoadIcons()
        {
            if (_searchIcon == null)
            {
                string path = "Packages/com.slax.questsystem/Editor/Textures/search.png";
                _searchIcon = (Texture2D)AssetDatabase.LoadAssetAtPath(path, typeof(Texture2D));
            }

            if (_refreshIcon == null)
            {
                string path = "Packages/com.slax.questsystem/Editor/Textures/refresh.png";
                _refreshIcon = (Texture2D)AssetDatabase.LoadAssetAtPath(path, typeof(Texture2D));
            }
        }

        GUIStyle GetSquareButtonStyle(int size)
        {
            GUIStyle buttonStyle = new GUIStyle(GUI.skin.button);
            buttonStyle.padding = new RectOffset(5, 5, 5, 5);
            buttonStyle.fixedHeight = size;
            buttonStyle.fixedWidth = size;
            return buttonStyle;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;
using System;

namespace Slax.QuestSystem
{
    /// <summary>
    /// Manager for all created and ongoing quests. Handles interactions and holds all relations to necessary entities.
    /// </summary>
    public class QuestManager : MonoBehaviour
    {
        [SerializeField, Tooltip("The game's quest lines.")] protected List<QuestLineSO> _questLines = new List<QuestLineSO>();

        /// <summary>List of all quest lines in the game</summary>
        public List<QuestLineSO> QuestLines => _questLines;

        [SerializeField] protected SaveType _saveType;
        [SerializeField] protected ReturnType _returnType;
        [SerializeField] protected string _saveFileName = "quests.savegame";

        [SerializeField] protected bool _grantRewards = true;

        public SaveType SaveType => _saveType;
        public ReturnType ReturnType => _returnType;

        /// <summary>
        /// Event fired when a step is started. The QuestEventInfo will hold the appropriate info to know if it is a Quest start
        /// or a QuestLine start for any listener to process
        /// </summary>
        public UnityAction<QuestEventInfo> OnStepStart = delegate { };

        /// <summary>
        /// Event fired when a step is completed but the quest is not completed yet
        /// </summary>
        public UnityAction<QuestEventInfo> OnStepComplete = delegate { };

        /// <summary>
        /// Event fired when a step is completed, completing the associated Quest
        /// but not the QuestLine
        /// </summary>
        public UnityAction<QuestEventInfo> OnQuestComplete = delegate { };

        /// <summary>
        /// Event fired when a step is completed, completing the associated Quest and QuestLine with it
        /// </summary>
        public UnityAction<QuestEventInfo> OnQuestLineComplete = delegate { };

        /// <summary>
        /// Event fired when a step is started but there are some missing step requirements
        /// </summary>
        public UnityAction<QuestEventInfo> OnMissingRequirements = delegate { };

        /// <summary>
        /// Event fired when a step is started but there are some missing step requirements
        /// </summary>
        public UnityAction<QuestEventInfo> OnStepStartConditionsNotMet = delegate { };

        /// <summary>
        /// Event fired when a step is started but there are some missing step requirements
        /// </summary>
        public UnityAction<QuestEventInfo> OnStepCompleteConditionsNotMet = delegate { };

        /// <summary>
        /// Singleton instance of the QuestManager
        /// </summary>
        public static QuestManager Instance { get; protected set; }

        #region MonoBehaviour

        protected virtual void Awake()
        {
            if (Instance != null)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);

            // If a custom save type is used, Initialize should be called directly with the data
            // from another custom script
            if (_saveType == SaveType.Internal)
            {
                string saveData;
                bool fileExisted = FileManager.LoadFromFile(_saveFileName, out saveData);
                if (!fileExisted)
                {
                    ResetAllQuests();
                    Log($"Quests save file at {_saveFileName} did not exist. Quest Manager is set to default values.");
                    SubscribeToQuestEvents();
                }
                else
                {
                    Initialize(saveData);
                }
            }
        }
        protected virtual void OnDisable()
        {
            UnsuscribeFromQuestEvents();
        }

        #endregion

        #region Setup And Initialization

        /// <summary>
        /// Sets up the Quest Manager from the save data when using json data such as 
        /// <para>
        /// <example>{"Steps":["QL1_Q1_S1","QL1_Q1_S2","QL1_Q2_S1"]}</example>
        /// </para>
        /// </summary>
        public virtual void Initialize(string jsonData)
        {
            SaveData save = JsonUtility.FromJson<SaveData>(jsonData);
            Log(save);
            Initialize(save.Steps);
        }

        /// <summary>
        /// Initializes the Quest Manager with save data when using List<string> saved data.
        /// Basically runs through all scriptable objects in the questlines and sets the state
        /// of the steps to the saved state.
        /// </summary>
        public virtual void Initialize(List<SavedStep> savedSteps)
        {
            // Start by resetting all data
            ResetAllQuests();

            foreach (SavedStep savedStep in savedSteps)
            {
                QuestLineSO questLine = _questLines.Find(ql => ql.Quests.Find(q => q.Steps.Find(s => s.name == savedStep.Step)));
                if (!questLine) continue;
                int questIdx = questLine.Quests.FindIndex(q => q.Steps.Find(s => s.name == savedStep.Step));
                if (questIdx == -1) continue;
                int idx = questLine.Quests[questIdx].Steps.FindIndex(s => s.name == savedStep.Step);
                if (idx == -1) continue;
                questLine.Quests[questIdx].Steps[idx].InitAs(savedStep.State);
            }

            SubscribeToQuestEvents();
        }

        public QuestManager SetGrantRewards(bool grantRewards)
        {
            _grantRewards = grantRewards;
            return this;
        }

        /// <summary>Subscribes to essential events fired by quests and questlines</summary>
        protected virtual void SubscribeToQuestEvents()
        {
            foreach (QuestLineSO questLine in _questLines)
            {
                questLine.Initialize();

                questLine.OnCompleted += HandleQuestLineCompletedEvent;
                questLine.OnProgress += HandleQuestCompletedEvent;

                foreach (QuestSO quest in questLine.Quests)
                {
                    if (!quest.Completed)
                    {
                        quest.OnProgress += HandleStepCompletedEvent;
                    }

                    foreach (QuestStepSO step in quest.Steps)
                    {
                        if (step.State == StepState.NotStarted)
                        {
                            step.OnStarted += HandleStepStartEvent;
                            step.OnMissingRequirements += HandleStepRequirementsNotMetEvent;
                            step.OnStartConditionsNotMet += HandleStepStartConditionsNotMetEvent;
                        }

                        if (step.State == StepState.Started)
                        {
                            step.OnCompleteConditionsNotMet += HandleStepCompleteConditionsNotMetEvent;
                        }
                    }
                }
            }
        }

        protected virtual void UnsuscribeFromQuestEvents()
        {
            foreach (QuestLineSO questLine in _questLines)
            {
                questLine.OnCompleted -= HandleQuestLineCompletedEvent;
                questLine.OnProgress -= HandleQuestCompletedEvent;

                foreach (QuestSO quest in questLine.Quests)
                {
                    quest.OnProgress -= HandleStepCompletedEvent;

                    foreach (QuestStepSO step in quest.Steps)
                    {
                        step.OnStarted -= HandleStepStartEvent;
                        step.OnMissingRequirements -= HandleStepRequirementsNotMetEvent;
                        step.OnStartConditionsNotMet -= HandleStepStartConditionsNotMetEvent;
                        step.OnCompleteConditionsNotMet -= HandleStepCompleteConditionsNotMetEvent;
                    }
                }
            }
        }

        /// <summary>
        /// Resets all Quest Steps to false before loading in save data
        /// </summary>
        protected virtual void ResetAllQuests()
        {
            foreach (QuestLineSO questLine in _questLines)
            {
                foreach (QuestSO quest in questLine.Quests)
                {
                    foreach (QuestStepSO step in quest.Steps)
                    {
                        step.InitAs(StepState.NotStarted);
                    }
                }
            }
        }

        #endregion

        #region Quest Events

        ///<summary>
        /// Handles the event fired from a Step when the step attemps to start but there 
        /// are some missing step requirements.
        ///</summary>
        ///<param name="requirements">The list of requirements that are missing</param>
        protected virtual void HandleStepRequirementsNotMetEvent(QuestStepSO notifier, List<QuestStepSO> requirements)
        {
            QuestEventInfo eventInfo = PrepareQuestEventInfo(notifier);
            eventInfo.Requirements = requirements;
            eventInfo.ConditionType = QuestEventInfo.ConditionNotMetType.StepRequirements;
            OnMissingRequirements.Invoke(eventInfo);
        }


        ///<summary>
        /// Handles the event fired from a Step when the step attemps to start but there
        /// are some missing step start conditions.
        /// </summary>
        /// <param name="step">The step that was started</param>
        /// <param name="conditions">The list of conditions that were not met</param>
        protected virtual void HandleStepStartConditionsNotMetEvent(QuestStepSO step, List<IQuestCondition> conditions)
        {
            QuestEventInfo eventInfo = PrepareQuestEventInfo(step);
            eventInfo.Conditions = conditions;
            eventInfo.ConditionType = QuestEventInfo.ConditionNotMetType.StepStartConditions;
            OnStepStartConditionsNotMet.Invoke(eventInfo);
        }

        /// <summary>
        /// Handles the event fired from a Step when the step attemps to complete but there
        /// are some missing step complete conditions.
        /// </summary>
        /// <param name="step">The step that was completed</param>
        /// <param name="conditions">The list of conditions that were not met</param>
        protected virtual void HandleStepCompleteConditionsNotMetEvent(QuestStepSO step, List<IQuestCondition> conditions)
        {
            QuestEventInfo eventInfo = PrepareQuestEventInfo(step);
            eventInfo.Conditions = conditions;
            eventInfo.ConditionType = QuestEventInfo.ConditionNotMetType.StepCompleteConditions;
            OnStepCompleteConditionsNotMet.Invoke(eventInfo);
        }

        /// <summary>
        /// Handles the event fired from a Step when the
        /// step starts. The QuestEventInfo will hold the
        /// appropriate info to know if it is a Quest start
        /// or a QuestLine start for any listener to process
        /// </summary>
        /// <param name="step">The step that was started</param>
        protected virtual void HandleStepStartEvent(QuestStepSO step)
        {
            step.OnStarted -= HandleStepStartEvent;
            QuestEventInfo eventInfo = PrepareQuestEventInfo(step);
            OnStepStart.Invoke(eventInfo);
        }

        /// <summary>
        /// Handles the event fired from a Quest whenever a step
        /// is completed but the quest is not completed yet
        /// </summary>
        /// <param name="quest">The quest that the step belongs to</param>
        /// <param name="step">The step that was completed</param>
        protected virtual void HandleStepCompletedEvent(QuestSO quest, QuestStepSO step)
        {
            quest.OnProgress -= HandleStepCompletedEvent;

            if (_grantRewards)
            {
                foreach (IQuestReward reward in step.Rewards)
                {
                    reward.GrantReward();
                }
            }

            QuestEventInfo eventInfo = PrepareQuestEventInfo(step);
            OnStepComplete.Invoke(eventInfo);
        }

        /// <summary>
        /// Handles the event fired from the QuestLine whenever a step is completed
        /// and the associated Quest is completed as well but the associated QuestLine
        /// is not yet completed
        /// </summary>
        /// <param name="questLine">The questline that the quest belongs to</param>
        /// <param name="quest">The quest that was completed</param>
        /// <param name="step">The step that was completed</param>
        protected virtual void HandleQuestCompletedEvent(QuestLineSO questLine, QuestSO quest, QuestStepSO step)
        {
            questLine.OnProgress -= HandleQuestCompletedEvent;

            if (_grantRewards)
            {
                // We also grant the rewards for step here because the
                // step completion event is not fired when the quest is completed
                foreach (IQuestReward reward in step.Rewards)
                {
                    reward.GrantReward();
                }

                foreach (IQuestReward reward in quest.Rewards)
                {
                    reward.GrantReward();
                }
            }

            QuestEventInfo eventInfo = new QuestEventInfo(questLine, quest, step);
            OnQuestComplete.Invoke(eventInfo);
        }

        /// <summary>
        /// Handles the event fired from the QuestLine whenever a step is completed,
        /// completing the associated Quest and QuestLine with it. It is possible to handle
        /// individual completion of the step and quest with this event as the QuestEventInfo
        /// holds the information for the completed QuestLine as well as what Quest and Step
        /// triggered the completion
        /// </summary>
        /// <param name="questLine">The questline that was completed</param>
        /// <param name="quest">The quest that was completed</param>
        /// <param name="step">The step that was completed</param>
        protected virtual void HandleQuestLineCompletedEvent(QuestLineSO questLine, QuestSO quest, QuestStepSO step)
        {
            questLine.OnCompleted -= HandleQuestLineCompletedEvent;

            if (_grantRewards)
            {
                // We also grant the rewards for step and quest here because the
                // step / quest completion events are not fired when the questline
                // is completed.
                foreach (IQuestReward reward in step.Rewards)
                {
                    reward.GrantReward();
                }

                foreach (IQuestReward reward in quest.Rewards)
                {
                    reward.GrantReward();
                }

                foreach (IQuestReward reward in questLine.Rewards)
                {
                    reward.GrantReward();
                }
            }

            OnQuestLineComplete.Invoke(new QuestEventInfo(questLine, quest, step));
        }

        #endregion

        #region Helpers

        /// <summary>
        /// Returns the QuestSO inside of which the QuestStepSO is found
        /// </summary>
        /// <param name="questStep">The quest step to look for in the available questlines</param>
        public virtual QuestSO QuestFromStep(QuestStepSO questStep)
        {
            QuestLineSO questLine = QuestLineFromQuestStep(questStep);
            if (!questLine) throw new Exception("No QuestLine found for this Quest Step");
            QuestSO quest = questLine.Quests.Find(q => q.Steps.Find(s => s.name == questStep.name));
            return quest;
        }

        /// <summary>
        /// Returns the QuestLineSO inside of which the QuestSO is found
        /// </summary>
        /// <param name="quest">The quest to look for in the available questlines</param>
        public virtual QuestLineSO QuestLineFromQuest(QuestSO quest) => _questLines.Find(ql => ql.Quests.Find(q => q.name == quest.name));

        /// <summary>
        /// Returns the QuestLineSO inside of which the QuestStepSO is found
        /// </summary>
        /// <param name="step">The quest step to look for in the available questlines</param>
        public virtual QuestLineSO QuestLineFromQuestStep(QuestStepSO step) => _questLines.Find(ql => ql.Quests.Find(q => q.Steps.Find(s => s.name == step.name)));

        /// <summary>Prepares the data to be sent by Quest Manager events</summary>
        /// <param name="step">The step for which the event is being prepared</param>
        protected virtual QuestEventInfo PrepareQuestEventInfo(QuestStepSO step)
        {
            QuestLineSO questLine = QuestLineFromQuestStep(step);
            QuestSO quest = QuestFromStep(step);
            return new QuestEventInfo(questLine, quest, step);
        }

        #endregion

        /// <summary>
        /// Returns the Done Quest Steps List as JSON parsed data or
        /// directly as List<SavedStep> depending on the set ReturnType
        /// </summary>
        [ContextMenu("Save")]
        public virtual dynamic CreateSaveData()
        {
            SaveData save = new SaveData();
            foreach (QuestLineSO questLine in _questLines)
            {
                foreach (QuestSO quest in questLine.Quests)
                {
                    foreach (QuestStepSO step in quest.Steps)
                    {
                        save.Steps.Add(new SavedStep(step.name, step.State));
                    }
                }
            }

            string saveDataJSON = JsonUtility.ToJson(save);

            if (_saveType == SaveType.Custom)
            {
                if (_returnType == ReturnType.StepList) return save.Steps;
                return saveDataJSON;
            }

            FileManager.WriteToFile(_saveFileName, saveDataJSON);
            return _returnType == ReturnType.JSON ? saveDataJSON : save.Steps;
        }

#if UNITY_EDITOR
        #region Editor Methods

        [SerializeField] protected bool _logMessages = false;

        protected void Log(object message)
        {
            if (_logMessages) Debug.Log(message);
        }

        public void ManualReset()
        {
            ResetAllQuests();
            Log("Quest Manager resetted, all quests marked as not completed.");
        }

        public void ManualSave()
        {
            var data = CreateSaveData();
            if (data is string)
            {
                if (_saveType == SaveType.Internal)
                {
                    Log($"Saved Quests Data to {_saveFileName}");
                    return;
                }
            }

            Log($"Quest Manager save type not set as internal. Returning data as : {data}");
        }

        #endregion
#endif
    }

    /// <summary>
    /// Sets the way the quests will be saved. Internal is handled by the Quest System and Custom
    /// simply sends back the data in the selected format to plug in any custom save system
    /// </summary>
    public enum SaveType
    {
        /// <summary>
        /// Setting save type to internal will let the QuestSystem manage the quest savefile
        /// By default it will read/write to quests.savegame, but this is customizable
        /// </summary>
        Internal,

        /// <summary>
        /// If you want to use a custom save system, setting this value will return the data in
        /// the type selected by the ReturnType field
        /// </summary>
        Custom,
    }

    /// <summary>
    /// Sets the type of data returned in a custom save type
    /// </summary>
    public enum ReturnType
    {
        /// <summary>
        /// Setting this return type value will return data in the following format : {"DoneQuestSteps":["QL1_Q1_S1","QL1_Q1_S2","QL1_Q2_S1"]}
        /// </summary>
        JSON,

        /// <summary>
        /// Setting this return type value will return data as a List<string> with the names/ids of the completed quests
        /// allowing for custom processing of the data before save if needed
        /// </summary>
        StepList,
    }

    /// <summary>
    /// The completion state of a step. This information is used when saving the steps to disk
    /// </summary>
    public enum StepState
    {
        NotStarted = 0,
        Started = 1,
        Completed = 2,
    }

    /// <summary>
    /// Information sent from unity actions / events on certain triggers
    /// such as quest start / end / checkpoint for external managers (like UI)
    /// to be able to display or use such information
    /// </summary>
    public struct QuestEventInfo
    {
        /// <summary>
        /// The type of condition that was not met, set to None if it isn't an event
        /// for conditions that were not met.
        /// </summary>
        public enum ConditionNotMetType
        {
            None,
            StepRequirements,
            StepStartConditions,
            StepCompleteConditions,
        }

        /// <summary>The type of condition that was not met</summary>
        public ConditionNotMetType ConditionType;

        /// <summary>The current questline</summary>
        public QuestLineSO QuestLine;

        /// <summary>The current quest for which the event was sent</summary>
        public QuestSO Quest;

        /// <summary>The current step for which the event was sent</summary>
        public QuestStepSO Step;

        /// <summary>If the step validated was the first step, meaning the quest just started</summary>
        public bool IsQuestStart;

        /// <summary>If the step validated was the first step of the quest & of the first quest of the questline</summary>
        public bool IsQuestLineStart;

        /// <summary>The list of conditions that were not met for the step to start / complete</summary>
        public List<IQuestCondition> Conditions;

        /// <summary>
        /// The list of step completion requirements that were not met for the step to start
        /// </summary>
        public List<QuestStepSO> Requirements;

        public QuestEventInfo(QuestLineSO questLine, QuestSO quest, QuestStepSO step, ConditionNotMetType conditionType = ConditionNotMetType.None)
        {
            QuestLine = questLine;
            Quest = quest;
            Step = step;
            IsQuestStart = quest.Steps.FindIndex(s => s.name == step.name) == 0;
            IsQuestLineStart = questLine.Quests.FindIndex(q => q.name == quest.name) == 0 && IsQuestStart;
            ConditionType = conditionType;
            Conditions = new List<IQuestCondition>();
            Requirements = new List<QuestStepSO>();
        }
    }
}

using UnityEngine;
using UnityEngine.Events;

namespace Slax.QuestSystem
{
    /// <summary>
    /// Event hub for the QuestManager. This class is used to listen to the 
    /// QuestManager events and trigger UnityEvents when they are fired.
    /// 
    /// <para>
    /// This class is to facilitate usage for those who prefer assigning UnityEvents
    /// in the inspector rather than subscribing to the events in code.
    /// </para>
    /// </summary>
    public class QuestManagerEventHub : MonoBehaviour
    {
        public UnityEvent<QuestEventInfo> OnMissingRequirements;
        public UnityEvent<QuestEventInfo> OnStepStartConditionsNotMet;
        public UnityEvent<QuestEventInfo> OnStepCompleteConditionsNotMet;
        public UnityEvent<QuestEventInfo> OnStepStart;
        public UnityEvent<QuestEventInfo> OnStepComplete;
        public UnityEvent<QuestEventInfo> OnQuestComplete;
        public UnityEvent<QuestEventInfo> OnQuestLineComplete;

        protected virtual void OnEnable()
        {
            QuestManager.Instance.OnMissingRequirements += ShowMissingRequirements;
            QuestManager.Instance.OnStepStartConditionsNotMet += ShowStepStartConditionsNotMet;
            QuestManager.Instance.OnStepCompleteConditionsNotMet += ShowStepCompleteConditionsNotMet;
            QuestManager.Instance.OnStepStart += ShowStepStart;
            QuestManager.Instance.OnStepComplete += ShowStepComplete;
            QuestManager.Instance.OnQuestComplete += ShowQuestComplete;
            QuestManager.Instance.OnQuestLineComplete += ShowQuestLineComplete;
        }

        protected virtual void OnDisable()
        {
            QuestManager.Instance.OnMissingRequirements -= ShowMissingRequirements;
            QuestManager.Instance.OnStepStartConditionsNotMet -= ShowStepStartConditionsNotMet;
            QuestManager.Instance.OnStepCompleteConditionsNotMet -= ShowStepCompleteConditionsNotMet;
            QuestManager.Instance.OnStepStart -= ShowStepStart;
            QuestManager.Instance.OnStepComplete -= ShowStepComplete;
            QuestManager.Instance.OnQuestComplete -= ShowQuestComplete;
            QuestManager.Instance.OnQuestLineComplete -= ShowQuestLineComplete;
        }

        protected virtual void ShowMissingRequirements(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Missing {eventInfo.Requirements.Count} requirements before starting this step !");
            {
                foreach (QuestStepSO req in eventInfo.Requirements)
                {
                    Log($"{req.DisplayName} from quest {eventInfo.Quest.DisplayName} is a required step.");
                }
            }
#endif
            OnMissingRequirements?.Invoke(eventInfo);
        }

        protected virtual void ShowStepStart(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            if (eventInfo.IsQuestLineStart)
            {
                Log($"Questline {eventInfo.QuestLine.DisplayName} start with quest {eventInfo.Quest.DisplayName} and step {eventInfo.Step.DisplayName}");
            }
            else if (eventInfo.IsQuestStart)
            {
                Log($"Quest {eventInfo.Quest.DisplayName}start and step {eventInfo.Step.DisplayName} start");
            }
            else
            {
                Log($"Step {eventInfo.Step.DisplayName} start");
            }
#endif
            OnStepStart?.Invoke(eventInfo);
        }

        protected virtual void ShowStepComplete(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Step {eventInfo.Step.DisplayName} completed !");
#endif
            OnStepComplete?.Invoke(eventInfo);
        }

        protected virtual void ShowQuestComplete(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Quest ${eventInfo.Quest.DisplayName} completed by completing {eventInfo.Step.DisplayName}");
#endif
            OnQuestComplete?.Invoke(eventInfo);
        }

        protected virtual void ShowQuestLineComplete(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Quest Line {eventInfo.QuestLine.DisplayName} completed by completing step {eventInfo.Step.DisplayName} of Quest {eventInfo.Quest.DisplayName}");
#endif
            OnQuestLineComplete?.Invoke(eventInfo);
        }

        protected virtual void ShowStepStartConditionsNotMet(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Step {eventInfo.Step.DisplayName} has {eventInfo.Conditions.Count} unmet start conditions !");
#endif
            OnStepStartConditionsNotMet?.Invoke(eventInfo);
        }

        protected virtual void ShowStepCompleteConditionsNotMet(QuestEventInfo eventInfo)
        {
#if UNITY_EDITOR
            Log($"Step {eventInfo.Step.DisplayName} has {eventInfo.Conditions.Count} unmet complete conditions !");
#endif
            OnStepCompleteConditionsNotMet?.Invoke(eventInfo);
        }

#if UNITY_EDITOR
        [SerializeField] private bool _logMessages = true;
        void Log(object msg)
        {
            if (_logMessages)
            {
                Debug.Log(msg);
            }
        }
#endif
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class Draggable : MonoBehaviour
{


    public bool isDragging = false;
    public GameObject invalidDragIndicator;

    private const float IS_DRAGGING_ALPHA = 0.5f;
    private const float IS_NOT_DRAGGING_ALPHA = 1f;

    public Vector3 preDragPosition;
    public Quaternion preDragRotation;


    // UNITY HOOKS

    void Start()
    {
        this.invalidDragIndicator.SetActive(false);
    }

    void Update()
    {
        if (this.isDragging)
        {
            this.CheckDragValidity();
        }
    }

    // INTF METHODS

    public void SetDragging(bool isDragging)
    {
        GameEntity geScript = this.GetComponent<GameEntity>();
        if (this.isDragging != isDragging)
        {
            // has started dragging
            if (isDragging)
            {
                // noop
            }
            // has been dropped
            else
            {
                this.CheckDragValidity();
            }
            // sorting layer for renderers
            string sortingLayer = isDragging ? GameSettings.SORTING_LAYER_ENTITY_DRAGGING : geScript.gridLayer;
            this.GetComponent<GameEntity>().SetRenderersSortingLayer(sortingLayer);
            // display based on drag state
            this.SetDraggingDisplay(isDragging);
        }
        this.isDragging = isDragging;
    }

    public bool PositionIsValid()
    {
        // check if drag position is valid by checking if another game entity is occupying the same position
        Vector3 pos = Functions.QuantizeVector(this.transform.position);
        string gridLayerName = this.GetComponent<GameEntity>().gridLayer;
        GameObject occupyingGameEntity = PlaySceneManager.instance.gameEntityManager.GetGameEntityAtPosition(gridLayerName, pos);
        GameEntityGridLayer gridLayer = PlaySceneManager.instance.gameEntityManager.GetGameEntityGridLayer(gridLayerName);
        bool positionIsValid = gridLayer.PositionIsValidAndFree(pos) || occupyingGameEntity == this.gameObject;
        return positionIsValid;
    }

    // IMPL METHODS

    private void CheckDragValidity()
    {
        // position is already occupied
        if (this.PositionIsValid())
        {
            this.invalidDragIndicator.SetActive(false);
        }
        // position is unoccupied
        else
        {
            this.invalidDragIndicator.SetActive(true);
        }
    }

    private void SetDraggingDisplay(bool isDragging)
    {
        float alpha = isDragging ? IS_DRAGGING_ALPHA : IS_NOT_DRAGGING_ALPHA;
        this.GetComponent<GameEntity>().SetSpriteRenderersOpacity(alpha);
    }


}

using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using UnityEngine;

public class GameSaveLoadManager : MonoBehaviour
{


    private const string SAVE_DIR = "/saves/";

    private readonly bool useLogging = false;


    // UNITY HOOKS 

    void Awake()
    {
        this.Initialize();
    }

    void Start() { }

    void Update() { }

    // INTF METHODS

    public void SaveGame(string saveName, Vector3 cameraPosition, float cameraSize, List<GameEntityState> gameEntityStates)
    {
        if (this.useLogging)
        {
            Debug.Log("Saving game to file: " + this.GetSavePath(saveName));
        }
        List<SerializableGameEntityState> serializableGameEntityStates = new();
        foreach (var gameEntity in gameEntityStates)
        {
            serializableGameEntityStates.Add(gameEntity.ToSerializable());
        }
        var gameData = new GameData(
            cameraPosition: new SerializableVector3(cameraPosition),
            cameraSize: cameraSize,
            gameEntityStates: serializableGameEntityStates,
            hotbarItemDatas: PlaySceneManager.instance.GetHotbarItemDatas()
        );
        using (FileStream stream = new(this.GetSavePath(saveName), FileMode.OpenOrCreate))
        {
            BinaryFormatter formatter = new();
            formatter.Serialize(stream, gameData);
        }
    }

    public GameData LoadGame(string saveName)
    {
        if (!this.SaveFileExists(saveName + ".dat"))
        {
            return null;
        }
        if (this.useLogging)
        {
            Debug.Log("Loading game from file: " + this.GetSavePath(saveName));
        }
        using (FileStream stream = new(this.GetSavePath(saveName), FileMode.Open))
        {
            BinaryFormatter formatter = new();
            var gameData = formatter.Deserialize(stream) as GameData;
            if (this.useLogging)
            {
                Debug.Log("Loaded from saved game data: " + gameData.GetStringFormattedData());
            }
            return gameData;
        }
    }

    public void DeleteSave(string saveName)
    {
        if (this.useLogging)
        {
            Debug.Log("Deleting save file: " + this.GetSavePath(saveName));
        }
        if (File.Exists(this.GetSavePath(saveName)))
        {
            File.Delete(this.GetSavePath(saveName));
        }
    }

    public void DeleteAllSaves()
    {
        if (this.useLogging)
        {
            Debug.Log("Deleting save files from directory: " + this.GetSaveDir());
        }
        if (Directory.Exists(this.GetSaveDir()))
        {
            Directory.Delete(this.GetSaveDir(), true);
        }
    }

    public List<string> GetAllSaveNames()
    {
        List<string> saveNames = new();
        if (Directory.Exists(this.GetSaveDir()))
        {
            foreach (var saveFilename in Directory.GetFiles(this.GetSaveDir()))
            {
                saveNames.Add(Path.GetFileNameWithoutExtension(saveFilename));
            }
        }
        return saveNames;
    }

    // IMPLEMENTATION METHODS

    private void Initialize()
    {
        if (!Directory.Exists(this.GetSaveDir()))
        {
            Directory.CreateDirectory(this.GetSaveDir());
        }
    }

    private string GetSaveDir()
    {
        return Application.persistentDataPath + SAVE_DIR;
    }

    private string GetSavePath(string saveName)
    {
        return Application.persistentDataPath + SAVE_DIR + saveName + ".dat";
    }

    private bool SaveFileExists(string saveFilename)
    {
        string saveDir = this.GetSaveDir();
        if (!Directory.Exists(Path.GetDirectoryName(saveDir)))
        {
            Debug.LogWarning("Save directory does not exist.");
            return false;
        }
        if (!File.Exists(saveDir + saveFilename))
        {
            Debug.LogWarning("Save file does not exist.");
            return false;
        }
        return true;
    }


}

