using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Drag a Rigidbody2D by selecting one of its colliders by pressing the mouse down.
/// When the collider is selected, add a TargetJoint2D.
/// While the mouse is moving, continually set the target to the mouse position.
/// When the mouse is released, the TargetJoint2D is deleted.`
/// </summary>
public class DragTarget : MonoBehaviour
{
	public LayerMask m_DragLayers;

	[Range (0.0f, 100.0f)]
	public float m_Damping = 1.0f;

	[Range (0.0f, 100.0f)]
	public float m_Frequency = 5.0f;

	public bool m_DrawDragLine = true;
	public Color m_Color = Color.cyan;

	private TargetJoint2D m_TargetJoint;

	void Update ()
	{
		var currentMouse = Mouse.current;

		// Calculate the world position for the mouse.
		var worldPos = Camera.main.ScreenToWorldPoint (currentMouse.position.value);

		if (currentMouse.leftButton.wasPressedThisFrame)
		{
			// Fetch the first collider.
			// NOTE: We could do this for multiple colliders.
			var collider = Physics2D.OverlapPoint (worldPos, m_DragLayers);
			if (!collider)
				return;

			// Fetch the collider body.
			var body = collider.attachedRigidbody;
			if (!body)
				return;

			// Add a target joint to the Rigidbody2D GameObject.
			m_TargetJoint = body.gameObject.AddComponent<TargetJoint2D> ();
			m_TargetJoint.dampingRatio = m_Damping;
			m_TargetJoint.frequency = m_Frequency;

			// Attach the anchor to the local-point where we clicked.
			m_TargetJoint.anchor = m_TargetJoint.transform.InverseTransformPoint (worldPos);		
		}
		else if (currentMouse.leftButton.wasReleasedThisFrame)
		{
			Destroy (m_TargetJoint);
			m_TargetJoint = null;
			return;
		}

		// Update the joint target.
		if (m_TargetJoint)
		{
			m_TargetJoint.target = worldPos;

			// Draw the line between the target and the joint anchor.
			if (m_DrawDragLine)
				Debug.DrawLine (m_TargetJoint.transform.TransformPoint (m_TargetJoint.anchor), worldPos, m_Color);
		}
	}
}

using UnityEngine;

public class Rigidbody2D_QuadraticDrag : MonoBehaviour
{
    public float DragCoefficient = 0.5f;

    private Rigidbody2D Body;

    void Start()
    {
        Body = GetComponent<Rigidbody2D>();
    }

    void FixedUpdate()
    {
        // Fetch the body velocity.
        var velocity = Body.linearVelocity;

        // Calculate the body speed.
        var speed = velocity.magnitude;
        if (speed > 0f)
        {
            // Calculate and apply the quadratic drag force (speed squared).
            var dragForce = (DragCoefficient * speed * speed) * -velocity.normalized;
            Body.AddForce(dragForce, ForceMode2D.Force);
        }
    }
}

using UnityEngine;
using UnityEngine.InputSystem;
using Unity.U2D.Physics;
using Unity.U2D.Physics.Extras;

public class DragScript : MonoBehaviour
{
    public bool UseDefaultWorld = true;
    public TestWorld World;
    public PhysicsQuery.QueryFilter QueryFilter = PhysicsQuery.QueryFilter.Everything;

    private Camera m_Camera;
    private PhysicsWorld m_World;
    private PhysicsBody m_DragGroundBody;
    private PhysicsRelativeJoint m_DragJoint;
    private DragMode m_DragMode = DragMode.Off;

    private enum DragMode
    {
        Off,
        Dragging
    }

    private void OnEnable()
    {
        m_Camera = Camera.main;
        m_World = UseDefaultWorld || World == null ? PhysicsWorld.defaultWorld : World.world; 
        m_DragGroundBody = m_World.CreateBody();
    }

    private void OnDisable()
    {
        if (m_DragGroundBody.isValid)
            m_DragGroundBody.Destroy();
    }

    private void Update()
    {
        var worldPosition = m_Camera.ScreenToWorldPoint(Mouse.current.position.value);

        if (m_DragMode == DragMode.Off && Mouse.current.leftButton.wasPressedThisFrame)
        {
            using var results = m_World.OverlapPoint(worldPosition, QueryFilter);
            if (results.Length == 0)
                return;

            var hitBody = results[0].shape.body;

            var relativeDefinition = new PhysicsRelativeJointDefinition
            {
                bodyA = m_DragGroundBody,
                bodyB = hitBody,
                localAnchorA = new PhysicsTransform(worldPosition),
                localAnchorB = hitBody.GetLocalPoint(worldPosition),
                springLinearFrequency = 7.5f,
                springLinearDamping = 0.7f,
                springMaxForce = 1000f * hitBody.mass * m_World.gravity.magnitude
            };

            m_DragJoint = m_World.CreateJoint(relativeDefinition);
            m_DragJoint.WakeBodies();

            m_DragMode = DragMode.Dragging;

            return;
        }

        if (m_DragMode == DragMode.Dragging)
        {
            if (Mouse.current.leftButton.wasReleasedThisFrame)
            {
                m_DragJoint.Destroy();
                m_DragMode = DragMode.Off;
                return;
            }

            // Update the target.
            m_DragJoint.localAnchorA = new PhysicsTransform(worldPosition);
            var bodyB = m_DragJoint.bodyB;
            bodyB.awake = true;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace UnityEditor
{
    //
    //  This extension allow to drag&drop subassets while pressing 'Alt'
    //

    [InitializeOnLoad]
    public static class SubAssetDragAndDrop
    {
        static SubAssetDragAndDrop()
        {
            EditorApplication.projectWindowItemOnGUI += OnProjectWindowItemOnGUI;
        }

        private static void OnProjectWindowItemOnGUI(string guid, Rect selectionRect)
        {
            // Break - key modifier doen't pressed
            var activated = Event.current.alt;
            if (activated == false) return;

            // Break - OnGUI() call not for mouse target
            var within = selectionRect.Contains(Event.current.mousePosition);
            if (within == false) return;

            // Break - destination match one of sources 
            var target = AssetDatabase.GUIDToAssetPath(guid);
            var targetInSources = Array.IndexOf(DragAndDrop.paths, target) != -1;
            if (targetInSources) return;

            // Break - unity default moving
            var targetIsFolder = AssetDatabase.IsValidFolder(target);
            if (targetIsFolder)
                foreach (var asset in DragAndDrop.objectReferences)
                    if (AssetDatabase.IsMainAsset(asset)) return;

            // Break - there is Unity restriction to use GameObjects as SubAssets
            foreach (var obj in DragAndDrop.objectReferences)
                if (obj is GameObject) return;

            if (Event.current.type == EventType.DragUpdated)
            {
                DragAndDrop.visualMode = DragAndDropVisualMode.Move;
                Event.current.Use();
            }
            else if (Event.current.type == EventType.DragPerform)
            {
                Move(DragAndDrop.objectReferences, target);
                DragAndDrop.AcceptDrag();
                Event.current.Use();
            }
        }

        private static void Move(IEnumerable<UnityEngine.Object> sources, string destinationPath)
        {
            var destinationIsFolder = AssetDatabase.IsValidFolder(destinationPath);

            foreach (var source in sources)
            {
                var sourcePath = AssetDatabase.GetAssetPath(source);
                var sourceIsMain = AssetDatabase.IsMainAsset(source);
                var sourceAssets = new List<UnityEngine.Object>() { source };
                if (sourceIsMain)
                    sourceAssets.AddRange(AssetDatabase.LoadAllAssetRepresentationsAtPath(sourcePath));

                // Peform move assets from source file to destination
                foreach (var asset in sourceAssets)
                    MoveAsset(asset, destinationPath);

                // Remove asset file if it is empty now
                if (sourceIsMain)
                    AssetDatabase.DeleteAsset(sourcePath);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
        }

        private static void MoveAsset(UnityEngine.Object asset, string destinationPath)
        {
            // Find hidden references (before source move)
            var assetRefs = GetHiddenReferences(asset);

            // Move asset
            var destinationIsFolder = AssetDatabase.IsValidFolder(destinationPath);
            if (destinationIsFolder)
            {
                var assetName = asset.name + "." + GetFileExtention(asset);
                var assetPath = Path.Combine(destinationPath, assetName);
                var assetUniquePath = AssetDatabase.GenerateUniqueAssetPath(assetPath);

                AssetDatabase.RemoveObjectFromAsset(asset);
                AssetDatabase.CreateAsset(asset, assetUniquePath);
            }
            else
            {
                AssetDatabase.RemoveObjectFromAsset(asset);
                AssetDatabase.AddObjectToAsset(asset, destinationPath);
            }

            // Move attached hidden references
            foreach (var reference in assetRefs)
            {
                AssetDatabase.RemoveObjectFromAsset(reference);
                AssetDatabase.AddObjectToAsset(reference, asset);
            }
        }

        private static List<UnityEngine.Object> GetHiddenReferences(UnityEngine.Object asset, string refsPath = null, List<UnityEngine.Object> refs = null)
        {
            if (refsPath == null)
                refsPath = AssetDatabase.GetAssetPath(asset);

            if (refs == null)
                refs = new List<UnityEngine.Object>();

            var iterator = new SerializedObject(asset).GetIterator();
            while (iterator.Next(true))
            {
                if (iterator.propertyType == SerializedPropertyType.ObjectReference)
                {
                    var obj = iterator.objectReferenceValue;
                    if (obj != null && (obj.hideFlags & HideFlags.HideInHierarchy) != 0)
                    {
                        if (refs.IndexOf(obj) == -1 && AssetDatabase.GetAssetPath(obj) == refsPath)
                        {
                            refs.Add(obj);
                            GetHiddenReferences(obj, refsPath, refs);
                        }
                    }
                }
            }

            return refs;
        }

        /// Thanks to mob-sakai (https://github.com/mob-sakai/SubAssetEditor) for full mapping list
        private static string GetFileExtention(UnityEngine.Object obj)
        {
            if (obj is AnimationClip)
                return "anim";
            else if (obj is UnityEditor.Animations.AnimatorController)
                return "controller";
            else if (obj is AnimatorOverrideController)
                return "overrideController";
            else if (obj is Material)
                return "mat";
            else if (obj is Texture)
                return "png";
            else if (obj is ComputeShader)
                return "compute";
            else if (obj is Shader)
                return "shader";
            else if (obj is Cubemap)
                return "cubemap";
            else if (obj is Flare)
                return "flare";
            else if (obj is ShaderVariantCollection)
                return "shadervariants";
            else if (obj is LightmapParameters)
                return "giparams";
            else if (obj is GUISkin)
                return "guiskin";
            else if (obj is PhysicMaterial)
                return "physicMaterial";
            else if (obj is PhysicsMaterial2D)
                return "physicsMaterial2D";
            else if (obj is UnityEngine.Audio.AudioMixer)
                return "mixer";
            else if (obj is UnityEngine.U2D.SpriteAtlas)
                return "spriteatlas";
            else if (obj is TextAsset)
                return "txt";
            else if (obj is GameObject)
                return "prefab";
            else if (obj is ScriptableObject)
                return "asset";

            return null;
        }
    }
}
